/// The composed system: one owned state and one bounded mailbox per machine,
/// and one bounded outbox per output port.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct System {
    sink_state: SinkState,
    sink_inbox: SinkInbox,
    source_state: SourceState,
    source_inbox: SourceInbox,
    report_outbox: ReportOutbox,
    tap_outbox: TapOutbox,
    next: usize,
}

impl System {
    const MACHINES: usize = 2;

    /// Every machine in its initial state, with empty mailboxes and outboxes.
    pub fn new() -> Self {
        Self {
            sink_state: zone_b::sink::init(),
            sink_inbox: SinkInbox::new(),
            source_state: zone_a::cell::source::init(),
            source_inbox: SourceInbox::new(),
            report_outbox: ReportOutbox::new(),
            tap_outbox: TapOutbox::new(),
            next: 0,
        }
    }

    /// Current state of `sink`. Read-only: only its own `step` changes it.
    pub fn sink_state(&self) -> SinkState {
        self.sink_state
    }

    /// The mailbox of `sink`, read-only.
    pub fn sink_inbox(&self) -> &SinkInbox {
        &self.sink_inbox
    }

    /// Current state of `source`. Read-only: only its own `step` changes it.
    pub fn source_state(&self) -> SourceState {
        self.source_state
    }

    /// The mailbox of `source`, read-only.
    pub fn source_inbox(&self) -> &SourceInbox {
        &self.source_inbox
    }

    /// The outbox of port `report`, read-only.
    pub fn report_outbox(&self) -> &ReportOutbox {
        &self.report_outbox
    }

    /// The outbox of port `tap`, read-only.
    pub fn tap_outbox(&self) -> &TapOutbox {
        &self.tap_outbox
    }

    /// Port `poke`: offers `message` to `source`. Accepted only if its mailbox has room;
    /// otherwise `Err(Rejected)`, and the caller keeps the message.
    pub fn send_poke(&mut self, message: PokeMessage) -> Result<(), Rejected> {
        let message = routes::port_poke(message);
        let message = zone_a::routes::port_zone_a_in(message);
        let input = zone_a::cell::routes::port_cell_in(message);
        if self.source_inbox.push(input) {
            Ok(())
        } else {
            Err(Rejected)
        }
    }

    /// Port `report`: removes and returns the oldest message the system has emitted
    /// there, if any. Taking a message makes room: a sender blocked by this outbox
    /// can then proceed.
    pub fn take_report(&mut self) -> Option<ReportMessage> {
        self.report_outbox.pop()
    }

    /// Port `tap`: removes and returns the oldest message the system has emitted
    /// there, if any. Taking a message makes room: a sender blocked by this outbox
    /// can then proceed.
    pub fn take_tap(&mut self) -> Option<TapMessage> {
        self.tap_outbox.pop()
    }

    /// True when no mailbox holds a message. Outboxes may still hold messages
    /// for the environment.
    pub fn is_settled(&self) -> bool {
        let mut settled = true;
        settled &= self.sink_inbox.is_empty();
        settled &= self.source_inbox.is_empty();
        settled
    }

    /// Serves the next machine, in round-robin order, whose delivery is enabled.
    pub fn step_once(&mut self) -> Progress {
        let mut blocked = false;
        let machine = (self.next) % Self::MACHINES;
        match self.attempt(machine) {
            Attempt::Delivered => {
                self.next = (machine + 1) % Self::MACHINES;
                return Progress::Delivered;
            }
            Attempt::Blocked => blocked = true,
            Attempt::Idle => {}
        }
        let machine = (self.next + 1) % Self::MACHINES;
        match self.attempt(machine) {
            Attempt::Delivered => {
                self.next = (machine + 1) % Self::MACHINES;
                return Progress::Delivered;
            }
            Attempt::Blocked => blocked = true,
            Attempt::Idle => {}
        }
        if blocked {
            Progress::Blocked
        } else {
            Progress::Settled
        }
    }

    /// Delivers until settled, blocked or `max_steps` deliveries.
    pub fn run(&mut self, max_steps: usize) -> Result<usize, Stopped> {
        for steps in 0..max_steps {
            match self.step_once() {
                Progress::Delivered => {}
                Progress::Settled => return Ok(steps),
                Progress::Blocked => return Err(Stopped::Blocked { steps }),
            }
        }
        if self.is_settled() {
            Ok(max_steps)
        } else {
            Err(Stopped::Budget { steps: max_steps })
        }
    }

    fn attempt(&mut self, machine: usize) -> Attempt {
        match machine {
            0 => self.attempt_sink(),
            1 => self.attempt_source(),
            _ => Attempt::Idle,
        }
    }

    fn attempt_sink(&mut self) -> Attempt {
        let input = match self.sink_inbox.peek() {
            Some(input) => input,
            None => return Attempt::Idle,
        };
        let (state, output) = zone_b::sink::step(self.sink_state, input);
        let m0 = match output {
            Some(output) => sink_route_0(output),
            None => None,
        };
        if m0.is_some() && self.report_outbox.is_full() {
            return Attempt::Blocked;
        }
        let _ = self.sink_inbox.pop();
        self.sink_state = state;
        if let Some(message) = m0 {
            let _ = self.report_outbox.push(message);
        }
        Attempt::Delivered
    }

    fn attempt_source(&mut self) -> Attempt {
        let input = match self.source_inbox.peek() {
            Some(input) => input,
            None => return Attempt::Idle,
        };
        let (state, output) = zone_a::cell::source::step(self.source_state, input);
        let m0 = match output {
            Some(output) => source_route_0(output),
            None => None,
        };
        let m1 = match output {
            Some(output) => source_route_1(output),
            None => None,
        };
        let m2 = match output {
            Some(output) => source_route_2(output),
            None => None,
        };
        let mut to_sink = 0;
        if m0.is_some() {
            to_sink += 1;
        }
        if m2.is_some() {
            to_sink += 1;
        }
        if self.sink_inbox.len() + to_sink > SINK_CAPACITY {
            return Attempt::Blocked;
        }
        if m1.is_some() && self.tap_outbox.is_full() {
            return Attempt::Blocked;
        }
        let _ = self.source_inbox.pop();
        self.source_state = state;
        if let Some(message) = m0 {
            let _ = self.sink_inbox.push(message);
        }
        if let Some(message) = m1 {
            let _ = self.tap_outbox.push(message);
        }
        if let Some(message) = m2 {
            let _ = self.sink_inbox.push(message);
        }
        Attempt::Delivered
    }
}

impl Default for System {
    fn default() -> Self {
        Self::new()
    }
}
